         .write_all(
             b"derrick upgrade is not yet available; future releases will use GitHub release assets\n",
         )
         .map_err(|source| crate::CliError::Io {
             path: std::path::PathBuf::from("<stdout>"),
             source,
         })?;
     Ok(CliExitCode::Success)
 }

