1. use std::fs;
2. use std::path::{Path, PathBuf};
3. 
4. use assert_cmd::Command;
5. use tempfile::TempDir;
6. 
7. type TestResult<T = ()> = Result<T, Box<dyn std::error::Error>>;
8. 
9. fn derrick() -> TestResult<Command> {
10.     Ok(Command::cargo_bin("derrick")?)
11. }
12. 
13. fn repo() -> TestResult<TempDir> {
14.     let dir = tempfile::tempdir()?;
15.     fs::create_dir(dir.path().join(".git"))?;
16.     Ok(dir)
17. }
18. 
19. fn greenfield(dir: &Path) -> TestResult<assert_cmd::assert::Assert> {
20.     Ok(derrick()?
21.         .current_dir(dir)
22.         .env("DERRICK_SKIP_PREREQS", "1")
23.         .args([
24.             "init",
25.             "--greenfield",
26.             "--site",
27.             "test",
28.             "--prefix",
29.             "tst",
30.             "--mode",
31.             "solo",
32.         ])
33.         .assert())
34. }
35. 
36. fn adopted_init(dir: &Path) -> TestResult<assert_cmd::assert::Assert> {
37.     fs::write(dir.join("AGENTS.md"), "# Agents\n")?;
38.     fs::write(dir.join("CLAUDE.md"), "# Claude\n")?;
39.     Ok(derrick()?
40.         .current_dir(dir)
41.         .env("DERRICK_SKIP_PREREQS", "1")
42.         .args(["init", "--site", "test", "--prefix", "tst"])
43.         .assert())
44. }
45. 
46. fn mock_path(dir: &Path, names: &[&str]) -> TestResult<PathBuf> {
47.     let bin_dir = dir.join("bin");
48.     fs::create_dir(&bin_dir)?;
49.     for name in names {
50.         let path = bin_dir.join(name);
51.         fs::write(&path, "#!/bin/sh\nexit 0\n")?;
52.         let mut permissions = fs::metadata(&path)?.permissions();
53.         #[cfg(unix)]
54.         {
55.             use std::os::unix::fs::PermissionsExt;
56.             permissions.set_mode(0o755);
57.         }
58. 
59.         fs::set_permissions(&path, permissions)?;
60.     }
61.     Ok(bin_dir)
62. }
63. 
64. fn mock_flow_path(dir: &Path) -> TestResult<PathBuf> {
65.     let bin_dir = dir.join("flow-bin");
66.     fs::create_dir(&bin_dir)?;
67.     write_executable(
68.         &bin_dir.join("claude"),
69.         r#"#!/bin/sh
70. # The prompt is always the last argument; flags like --print, --output-format,
71. # --dangerously-skip-permissions etc. precede it.
72. prompt=""
73. for arg in "$@"; do prompt="$arg"; done
74. # For specify, derrick pre-scaffolds the feature dir and amends the prompt
75. # with `Write the spec to: specs/<NNN>-<slug>/spec.md`. Extract that path so
76. # the mock writes to the same location derrick expects.
77. target=$(printf '%s' "$prompt" | /usr/bin/awk '/Write the spec to:/ { for (i=1;i<=NF;i++) if ($i ~ /^specs\//) { sub(/\/spec\.md$/, "", $i); print $i; exit } }')
